  ["Stereo module not installed."] = "A sztereó modul nincs telepítve.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "A motor hookjai nem töltődtek be, így minden alább hatástalan, és a headset az egyszerű mono úton fut. Vagy a CyberpunkVR_StereoModuleEnable értéke 0, vagy létezik a bin\\x64\\vrport_nostereo.txt. Lásd a \"Stereo:\" sort a cyberpunkvrport.log fájlban.",
  ["LEFT"] = "BAL",
  ["RIGHT"] = "JOBB",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Sztereó aktív  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Most nincs második szem -> mindkét szem MAIN-t kap (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Menükben és betöltéskor normális. Ha játék közben is így marad: a VRCAM komponens ki van kapcsolva, vagy a vrcam.json olyan kamerát nevez meg, amely a játékos entitásán nincs.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Sztereó küldés kikapcsolva -> mindkét szem MAIN-t kap (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "vrcam szem kora %u ms  (%u felett elavult)   szemküldések %llu",
  ["vrcam eye: never produced a frame"] = "vrcam szem: még nem készített képkockát",
  ["Send VRCAM to the %s EYE"] = "VRCAM küldése a(z) %s SZEMRE",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Ki = régi viselkedés, a MAIN mindkét szembe duplikálva.\nBe = a(z) %s szem a VRCAM nézet saját végső színét kapja --\nugyanazt a képet, amit az asztali tükör mutat --, a swapchain\nsRGB formátumába újrakódolva és a szem méretére skálázva.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "pillanatkép-másolatok %llu   kihagyások %llu   vrcam RTV-találatok %llu",
  ["Eye staleness limit (ms)"] = "Szem elavulási korlátja (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Meddig használható az utolsó VRCAM képkocka. Ezután a(z) %s\nszem visszavált MAIN-re -- egy befagyott szem, miközben a másik mozog,\nsokkal rosszabb látvány, mint a mono.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (a MAIN felskálázóját követi, nincs kapcsoló)",
  ["ON"] = "BE",
  ["off"] = "ki",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Be, amikor a MAIN DLSS-sel skáláz fel: a vrcam saját\nStreamline nézetablakot kap, és a célja alatt renderel.\nKi DLAA / TAA / felskálázó nélkül esetén. A játék grafikai\nbeállításaiban módosítható, nem itt.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "VRCAM vetítés igazítása a MAIN-hez  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "VRCAM komponens  (RTTI kapcsoló: BE/KI kényszerítése)",
  ["component %s   camera %s"] = "komponens %s   kamera %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "nézetcsomópontok: main %llu   egyéb %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "VRCAM tükör  (külön ablak, rögzítéshez)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Diagnosztika",
  ["Compact ADS camera telemetry (in-headset)"] = "Kompakt ADS kamera telemetria (a headsetben)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Egy kis panel, amely az F10 bezárása után is látszik, és megmutatja, mit tett a MOTOR a kamerával az irányzék felemelésekor:\neltérés és csúcs centiméterben, jobbra/előre/fel az irány saját bázisában, a csípőből tüzeléskor rögzített alaphoz képest.\nA sztereó küldést nem befolyásolja.",
  ["Telemetry X"] = "Telemetria X",
  ["Telemetry Y"] = "Telemetria Y",
  ["Normalised position in the eye image"] = "Normalizált pozíció a szem képén",
  ["Stereo logging -> cyberpunkvrport.log"] = "Sztereó naplózás -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "A VRCAM végső képének véglegesített pillanatképe",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Ki = a motor átmeneti céljának közvetlen olvasása. Ez a cél egy\nframe graph foglalás, amelyet egy későbbi menet újrahasznosít, emiatt\nváltakozott a kép világos/sötét között. Hagyja bekapcsolva.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Pillanatkép a tonemap csomópontnál a RenderFinal2D helyett",
  ["Node CPU profiler  (per-node self+incl ms)"] = "Csomópont CPU-profilozó  (saját+teljes ms csomópontonként)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "képkocka %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Csomópont-audit -> napló  (ablak nullázása)",
  ["top %d by self ms/frame   (main | vrcam)"] = "top %d saját ms/képkocka szerint   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Vezetés -- kéz a kormányon",
  ["Grab the wheel with the grips"] = "Kormány megfogása a markolatgombokkal",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "VEZETÉS közben vigye a kezét oda, ahol a vezetési animáció a\nkormányt (vagy a kormányrudat) tartja, és szorítsa meg a markolatgombot: a kar visszakerül\na játék saját animációjához -- kéz a kormányon, ujjak\nkörülötte -- a kontroller követése helyett. Engedje el, és visszatér\na kezéhez.\n\nA kezek függetlenek: az egyikkel tartsa a kormányt, a másikat\nfegyveren. Amíg egy kéz a kormányon van, az a markolatgomb semmi mást nem csinál (nincs\ntokból előhúzás, nincs tárfogás).",
  ["Grab radius (m)"] = "Fogási sugár (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Milyen közel kell lennie a kezének az animált kézhez, hogy a\nmarkolatgomb kormányfogásnak számítson. Nagyobb = könnyebb elkapni a\nnem látható kormányt; túl nagy, és az autóban minden fogás a kormányt fogja.",
  ["Car full lock at (deg)"] = "Teljes kormányzás ennél (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Kormányérzékenység: a kéz elfordulása a fogási ponttól a teljes kormányzásig.\nEgy kéz a fogás helyén kalibrált agyat használja; két kéz az összekötő vonalukat.\nKéz hozzáadása vagy elengedése megtartja az aktuális kormányzást.\n180 = fél fordulat ütközésig mindkét irányba (alapértelmezett). Kisebb = érzékenyebb.\nAz utastéri kormány natív útja kétszeres; a kerekek kormányzása nem változik.\nA teljes kormányzáson túli út ugyanazt a semleges helyzetet tartja.",
  ["Steering deadzone (deg)"] = "Kormányzás holtzónája (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Dőlés a középpont körül, amely egyáltalán nem kormányoz.\nNövelje, ha az autó elhúz, miközben egyenesen tartja a kormányt;\nitt minden fok egy fok holt kormány a középen kívül.\nA teljes tartomány így is a „Teljes kormányzás ennél” értéknél ér véget, ezért a\nholtzóna szélesítése nem okoz ugrást a kormányzásban.",
  ["Steering prediction"] = "Kormányzás előrejelzése",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Finoman előrejelzi a folytatódó kanyart a kéz friss mozgásából.\n8 ms-ra és 0.5°-ra korlátozva; a semleges helyzet nem változik.\nAz előrejelzés megáll szünetnél, irányváltásnál vagy fogásváltásnál.\nAlapértelmezetten ki. Egy kanyar kezdetét nem tudja előre jelezni.",
  ["Prediction horizon (ms)"] = "Előrejelzési horizont (ms)",
  ["Horn -- hand on the wheel hub"] = "Duda -- kéz a kormányagyon",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "VEZETÉS közben tegye a kezét a kormány KÖZEPÉRE -- oda, ahol\negy igazi dudát ütne --, és az autó dudál, amíg ott marad.\nNem kell markolatgomb; a kormányt FOGÓ kéz sosem dudál.",
  ["Horn hub radius (m)"] = "Dudaagy sugara (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Milyen közel a kormány középpontjához számít a kéz az agyon.\nNagyobb = a duda könnyebben megtalálható vakon; túl nagy,\nés eléri a peremet, így minden fogás dudál.",
  ["Trigger fires the gun while driving"] = "A ravasz lő vezetés közben",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Vegyen elő fegyvert a vezetőülésben, és a JOBB RAVASZ már nem\ngáz, hanem a fegyver: vezessen bal kézzel a kormányon, és\nlőjön a jobbal.\n\nA gáz RÖGZÜL azon az értéken, amely a fegyver előhúzásakor volt, így az\nautó tovább gurul, a BAL KAR előre/hátra pedig állítja a sebességet, amíg\nlő. Tegye el a fegyvert, és a ravasz ismét gáz.\n\nAmíg a fegyver kint van, a bal kar előre/hátra irányát a\nfinomhangolás foglalja: nincs dőlés / ringatás és nincs automatikus vezetési gesztus, amíg el nem teszi a fegyvert.",
  ["Throttle trim rate (/s)"] = "Gázállítás üteme (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "A gáz teljes útjának mekkora részét adja hozzá vagy\nveszi el a bal kar másodpercenként, amíg fegyver van elővéve.\n0.5 = két másodperc tartás alapjáratról padlógázig.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "vezetés %d   kormányon  L %d R %d   fogás  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "kormány  %+.1f°  ->  kar %+.2f     duda  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "ÜLŐ KAMERAELTOLÁS",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Az ÁLTALÁNOS fej-eltolások álló kalibrációk. Ülve a játék saját járműkamerája\nmár ott van, ahol lennie kell -- ezért a port járműben eldobja\na két automatikus értékét --, így egy álló eltolás elviszi a nézetet\naz ülésről ahelyett, hogy javítaná.\n\nEz a három hozzáadódik a fejcsúszkákhoz, amíg járműben ül, és\nfigyelmen kívül marad, amint kiszáll, így az autó és az utca külön\nhangolható. Nulla = az autó pontosan a mai eltolását tartja.",
