  ["Optical flow"] = "Optikai áramlás",
  ["Off (game vectors only)"] = "Ki (csak a játék vektorai)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "A játék mozgásvektorai már szinte minden mozgást leírnak; az optikai áramlás GPU-időt\nés memóriát ad ahhoz, ami kimarad belőlük (néhány részecske és effekt).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "Az NVIDIA képkockagenerálási modellje a játék mozgásvektorain és mélységén. Legjobb minőség, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Valós képkockák adaptív ütemezése",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Legfeljebb a headset frissítésének fele. Több GPU-időt hagy a generált képkockáknak, ha a szomszédos valós képkockák lemaradnak.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "A játék mozgásvektorait és mélységét használja mindkét szemben. Egy köztes képkockát illeszt a valós képkockák közé.",
  ["HUD"] = "HUD",
