  ["Follow"] = "Követés",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "A kúpon túl utoléri, vagy 3 másodperc nyugalom után, ha a legyezési eltérés benne 10° fölött van.",
