  ["Interaction free-look cone"] = "Interakciók szabad körülnézési kúpja",
  ["Loot free-look cone"] = "Zsákmány szabad körülnézési kúpja",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "A zsákmánypanel és a tárgyleírás látható ideje alatt használatos. Alapértelmezett: 10°.",
  ["Interaction distance"] = "Interakciók távolsága",
  ["Interaction FOV"] = "Interakciók FOV",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Az interakciós jelzések és a párbeszédválasztások ezen a panelen osztoznak. Csak a kúpon túl követ; nyugalomban nincs késleltetett utolérés.",
  ["Element"] = "Elem",
  ["Not currently visible in gameplay; settings are still saved."] = "Jelenleg nem látható a játékban; a beállítások így is mentődnek.",
