  ["Size"] = "Méret",
  ["Opacity"] = "Átlátszatlanság",
  ["Reset element"] = "Elem visszaállítása",
  ["Reset all elements"] = "Minden elem visszaállítása",
  ["CONTROLS"] = "VEZÉRLÉS",
  ["DRIVING"] = "VEZETÉS",
  ["BINDINGS"] = "HOZZÁRENDELÉSEK",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Mozgás, célzás és fizikai interakciós gyorsparancsok.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Kézzel célzás  (ki = különválasztott VR fejcélzás)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "BE (kézzel célzás): a kontroller irányítja a fegyvert, a VRIK mozgatja a karokat.\nKI (különválasztott VR fejcélzás): a FEGYVER a fejét követi, a játék\nmegtartja a pozícióját és ADS-animációit, a VRIK pedig elengedi\na fegyveres kart. A lövés mindkét esetben a valódi csőtorkolatból indul, golyóknál\nés lövedékeknél egyaránt, a célzás közbeni szabad körülnézés pedig megmarad.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Lézerpont célzáskor (ahová a golyó talál)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "A fegyver valódi csőtorkolat-irányából a játék kameráján át\nvetített piros pont -- pontosan jelzi, hová repül a golyó.",
  ["Controller vibration"] = "Kontroller rezgés",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Haptika: minden lövés fegyverosztály szerint (pisztoly, puska, sörétes, mesterlövész),\nközelharci blokk és hárítás, golyóblokk és -elterelés, övelem elérése,\ngránát biztosítószegének kihúzása. Kétkezes fogás: mindkét kéz; egykezes: egy.",
  ["Vibration strength"] = "Rezgés erőssége",
  ["Enable VR -> XInput merge"] = "VR -> XInput összevonás bekapcsolása",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Minden lekérdezésnél összevonja (OR) a VR kontrollerek állapotát a 0. XInput gamepadbe.\nKi = a játék csak fizikai kontrollert lát / semmit.",
  ["Weapon holsters (reach + right grip)"] = "Fegyvertokok (nyúlás + jobb markolatgomb)",
  ["Immersive holsters"] = "Magával ragadó fegyvertokok",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "BE - a fegyvert a LÁTHATÓ tok választja ki, amelyhez nyúl:\n      jobb váll felett = elsődleges fegyver (puska / mesterlövész),\n      csípő katanával = közelharc, csípő pisztollyal = oldalfegyver.\nKI - a látható tokok figyelmen kívül, zónánként rögzített hely:\n      váll felett = EquipmentSlot1, jobb csípő = Slot2, bal csípő = Slot3.\nNyúljon a zónához, és szorítsa meg a JOBB markolatgombot a felszereléshez / eltevéshez.",
  ["Locomotion direction"] = "Mozgás iránya",
  ["Analog movement"] = "Analóg mozgás",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Be: a sebesség a bal kar kitérését követi. Ki: a jelenlegi fix sebességű mozgás (alapértelmezett).\nA járművek irányítása megtartja a jelenlegi reakcióját.",
  ["Left stick deadzone"] = "Bal kar holtzónája",
  ["Right stick deadzone"] = "Jobb kar holtzónája",
  ["Full input threshold"] = "Teljes bemenet küszöbe",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Az a nyers kitérés, amely teljes analóg bemenetet ad, és sprintet, kitérést és guggolást indít.\nA holtzóna és e küszöb közötti hasznos út 0-100%%-nak felel meg.",
  ["Game (camera)"] = "Játék (kamera)",
  ["HMD (head)"] = "HMD (fej)",
  ["Left hand"] = "Bal kéz",
  ["Right hand"] = "Jobb kéz",
  ["Move source"] = "Mozgás forrása",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Játék    - a bal kar arra visz, amerre a kamera néz (eredeti).\nHMD      - a bal kar arra visz, amerre a headset néz.\nBal/jobb kéz - arra visz, amerre a kiválasztott kontroller mutat.\nA járművek mindig a játék irányát tartják.",
  ["Breaststroke swimming"] = "Mellúszás",
  ["Physical crouch"] = "Fizikai guggolás",
  ["Physical crouch depth"] = "Fizikai guggolás mélysége",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Magasságvesztés a mért dőlés után. Felegyenesedéskor a fizikai guggolás megszűnik.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "Vízben: nyújtsa előre mindkét kezét, tárja szét, és húzza hátra.\nA mozgás a húzás közben indul. A lassú tempók normál úszást adnak; a gyors húzások gyorsítanak.\nArra úszik, amerre a headset mutat, felfelé/lefelé is; kar nem kell.\nFelemelkedéshez emelje szétválasztott kezeit mellkasmagasságba, és nyomja le mindkettőt.\nIsmételje a tempókat a továbbhaladáshoz. Megálláshoz húzza hátra a bal kart.",
  ["Ladder grip climbing"] = "Létramászás markolattal",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Fogjon meg egy oldalsó korlátot vagy fokot. Húzza le a kezét a felfelé mászáshoz,\nvagy mozgassa fel a lefelé mászáshoz. Engedje el a megálláshoz. A natív medence és lábak a létrán maradnak.",
  ["Auto finish near ladder top"] = "Automatikus befejezés a létra tetejénél",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "A tetőhöz közeli felfelé húzás után befejezi a mászást, még ha el is engedi a fogást.\nMozdítsa a kart, vagy nyomja felfelé a tartó kezet a megszakításhoz.",
  ["Ladder finish distance"] = "Létra befejezési távolsága",
  ["Turning (right stick)"] = "Fordulás (jobb kar)",
  ["Snap turn"] = "Lépésenkénti fordulás",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "A jobb kar X tengelyét különálló fordulási lépésekké alakítja\nfolyamatos forgás helyett. Segít a mozgásbetegség ellen.",
  ["Snap angle"] = "Lépés szöge",
  ["STEREO"] = "SZTEREÓ",
  ["PERFORMANCE"] = "TELJESÍTMÉNY",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Játék beállítása",
  ["Off (higher FPS)"] = "Ki (magasabb FPS)",
  ["On (lower latency)"] = "Be (kisebb késleltetés)",
  ["On + Boost"] = "Be + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "A Ki javíthatja a GPU-kihasználtságot és az FPS-t, de növelheti a bemeneti késleltetést.",
  ["On"] = "Be",
  ["Waiting for renderer"] = "Várakozás a renderelőre",
  ["Applied: %s"] = "Alkalmazva: %s",
  ["STEREO VIEW"] = "SZTEREÓ NÉZET",
  ["Mono mode"] = "Mono mód",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Egy kép mindkét szemnek, egyszer renderelve a fej közepéből:\nnincs mélység, a legtöbb képkocka. A motor sztereója és a második nézet ki van kapcsolva.",
  ["Restart the game to apply"] = "Indítsd újra a játékot az alkalmazáshoz",
  ["Motion prediction (ms)"] = "Mozgás előrejelzése (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Ennyi ms-mal előre jelzi a fejpózt a fej\nsebessége alapján, elrejtve a rendereléstől a fotonokig tartó késleltetést. 0 = ki.\nNövelje, amíg a mozgás reszponzív nem lesz túllövés nélkül.",
  ["Stereo separation x"] = "Sztereó távolság x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Az automatikus IPD személyes finomhangolása. 1.0 = kalibrált természetes\ntávolság, a headset futtatókörnyezetének IPD-jéhez skálázva. Ízlés szerint\n0.8-1.2; a 3-5x eltúlozza a mélységet, és láthatóvá teszi\na szemek váltakozását a lapos monitoron teszteléshez.",
  ["World scale"] = "Világ mérete",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Együtt skálázza a szemtávolságot ÉS a fej elmozdulását.\nCsökkentse (pl. 0.8), hogy a világ\nNAGYOBBNAK / ön kisebbnek tűnjön; növelje a világ kicsinyítéséhez. Használja, ha V\nés az NPC-k túl nagynak tűnnek.",
  ["IPD scale"] = "IPD skála",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Szemtávolság-szorzó a futtatókörnyezet IPD-jére. 1.0 = semleges\nalap (+-0.033 m egy tipikus headseten).\nA sztereó mélységre hat (dioráma vagy óriás), NEM a monokuláris méretre.",
  ["Reuse last clean frame"] = "Utolsó tiszta képkocka újrahasználata",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Elavult ütemeknél újraküldi az utolsó tiszta rögzített szemet, és hagyja,\nhogy a kompozitor újravetítse, ahelyett hogy újra torzítaná az elavult\ntartalmat. Csökkentheti a küldési ütemet\na rögzítési ütem felé. Ki = mindig torzítja az elavult szemet.",
  ["Asymmetric projection"] = "Aszimmetrikus vetítés",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "BE: minden szem pontosan a saját középen kívüli lencseablakát rendereli\n(több panelterület kihasználva, négyzetes pixelek).\nKI: a legszélesebb félszögre méretezett szimmetrikus frustum.",
  ["AVATAR"] = "AVATÁR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "VR gyorsparancsok és alapértelmezett játékműveletek. A gombnevek a Touch / Xbox konvenciót követik; a játékműveletek a kontroller-hozzárendeléseit használják.",
  ["LEFT STICK"] = "BAL KAR",
  ["Move. Hold fully forward for 0.2 seconds to sprint."] = "Mozgás. Sprinthez tartsa teljesen előre 0.2 másodpercig.",
  ["RIGHT STICK  Left / right"] = "JOBB KAR  Balra / jobbra",
  ["Turn. Uses your snap-turn setting."] = "Fordulás. A lépésenkénti fordulás beállítását használja.",
  ["RIGHT STICK  Full up"] = "JOBB KAR  Teljesen fel",
