  ["GRIP  At the wheel"] = "MARKOLATGOMB  A kormánynál",
  ["Grab the wheel or handlebars with that hand. Release to let go."] = "Fogja meg a kormányt vagy a kormányrudat azzal a kézzel. Engedje el az elengedéshez.",
  ["GAME CAMERA"] = "JÁTÉKKAMERA",
  ["VR follows the camera chosen by the game, including third-person scenes. Driving and seated-camera options are in DRIVING."] = "A VR a játék által választott kamerát követi, a külső nézetes jeleneteket is. A vezetési és ülő kamera opciók a VEZETÉS alatt vannak.",
  ["L3 + R3  Hold 0.5 second"] = "L3 + R3  Tartás 0.5 másodpercig",
  ["Open or close the VR menu in front of you (as the right-hand swipe down does)."] = "A VR menü megnyitása vagy bezárása maga előtt (mint a jobb kéz lefelé legyintése).",
  ["Point + TRIGGER"] = "Mutatás + RAVASZ",
